            {
                m += 1;
                b[L][m] = a[i][j];
                if (m >= row - 1)
                {
                    L++;
                    m = -1;
                }
            }
        }
        for (int x = 0; x < col; x++)
        {
            for (int y = 0; y < row; y++)
                System.out.printf("%3d", b[x][y]);
