#define _CRT_SECURE_NO_WARNINGS
#include <stdio.h>
#define MAX 5 
int Stack[MAX];
int Top = -1;

int push(int ii) {
    Top++;
    if (Top >= MAX) {
        printf("Overflow \n");
        Top--;
        return -1;
    }
    Stack[Top] = ii;
    return 0;
}

int pop(void) {
    int r;
    if (Top < 0) {
        printf("Underflow \n");
        return -1;
    }
    r = Stack[Top];
    Top--;
    return r;
}

main() {
