        {
            printf("삽입할 숫자를 입력하세요.:");
            scanf("%d", &k);
            i = push(k);
            if (i == -1) break;
        }
        else if (j == 2)
        {
            i = pop();
            if (i == -1) break;
            else
                printf("제거한 자료는 %d입니다\n", i);
        }
        else break;
    }
    if (Top < 0)
        printf("스택에 자료가 없습니다.\n");
    else
    {
        printf("스택의 자료는 다음과 같습니다.\n");
        for (int i = Top; i >= 0; i--)
            printf("%10d\n", Stack[i]);
    }
}

